shaders.fragment:
float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123); }
float vnoise(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f);
return mix(mix(hash(i),hash(i+vec2(1,0)),f.x), mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x), f.y); }
float fbm2(vec2 p){ float s=0.0, a=0.5; for(int i=0;i<4;i++){ s+=a*vnoise(p); p*=2.03; a*=0.5; } return s; }
uniform float uPattern, uReveal, uErode, uFade, uTime, uGlow, uRimW, uWisp; uniform vec3 uC[5]; varying vec2 vUv;
void main(){
float u=vUv.x, v=vUv.y;
if (u > uReveal) discard;
float n = fbm2(vec2(u*7.0, v*4.0) + uTime*0.7);
if (u < uErode*1.2 - 0.1 + (n-0.5)*0.35) discard;
float streak = fbm2(vec2(u*2.5 - uTime*2.2, v*12.0));
float inner = v + (streak-0.5)*uWisp;
if (inner < 0.2) discard;
float t = clamp((inner-0.2)/0.8, 0.0, 1.0);
vec3 col; float hot = 0.0;
if (uPattern < 0.5) {
  float k = t*0.85 + (streak-0.5)*0.5 + 0.1;
  if (k < 0.3) col=uC[0]; else if (k < 0.55) col=uC[1]; else if (k < 0.8) { col=uC[2]; hot=0.6; } else { col=uC[3]; hot=1.0; }
} else if (uPattern < 1.5) {
  col = mix(uC[0], uC[1], smoothstep(0.0, 0.9, t)); col = mix(col, uC[2], smoothstep(0.55, 0.8, streak)*0.6);
  vec2 g = vec2(u*28.0, v*4.0); vec2 id = floor(g); vec2 f = fract(g)-0.5; float r = hash(id);
  if (r > 0.45) {
    vec2 o = (vec2(hash(id+3.1), hash(id+7.7))-0.5)*0.5; vec2 q = f-o; q.y *= 0.7;
    float s = mix(0.08, 0.24, hash(id+1.3)) * (0.75+0.25*sin(uTime*14.0 + r*40.0));
    float arms = max(0.0, 1.0 - abs(q.x*q.y)/(s*s*0.05)) * max(0.0, 1.0 - length(q)/s);
    float core = smoothstep(s*0.25, 0.0, length(q));
    col = mix(col, uC[3]*uGlow, clamp(arms*1.6 + core, 0.0, 1.0));
  }
  col = mix(col, uC[3], step(0.986, hash(floor(vec2(u*170.0, v*18.0))))*0.8);
} else if (uPattern < 2.5) {
  float k = t*0.8 + (streak-0.5)*0.45 + 0.1;
  if (k < 0.35) col=uC[0]; else if (k < 0.65) col=uC[1]; else { col=uC[2]; hot=0.7; }
} else {
  col = mix(uC[0], uC[1], smoothstep(0.0, 0.6, t)); col = mix(col, uC[2], smoothstep(0.5, 1.0, t));
  vec2 g = vec2(u*34.0, v*5.0); vec2 id = floor(g); vec2 f = fract(g)-0.5; f.y *= 0.8; float r = hash(id);
  if (r > 0.45) { float s = mix(0.12, 0.38, hash(id+2.0)); float box = max(abs(f.x), abs(f.y));
    if (r > 0.8) { if (box < s) { col = mix(col, uC[3], 0.85); hot = 0.5; } } else if (abs(box-s) < 0.045) col = mix(col, uC[3], 0.7); }
}
if (v > 1.0-uRimW) { col = uC[4]; hot = 1.0; }
else if (v > 1.0-uRimW*2.2) { col = mix(col, uC[3], 0.6); hot = max(hot, 0.6); }
col *= mix(1.0, uGlow, hot);
gl_FragColor = vec4(col, uFade);
}

