shaders.fragment:
uniform float uT, uGlow, uPuffMode, uSeed; uniform vec3 uFlash, uPuff; varying vec2 vUv;
void main(){
vec2 p=(vUv-0.5)*2.0; float grow=smoothstep(0.0,0.22,uT); float fade=1.0-smoothstep(0.35,1.0,uT);
vec4 col=vec4(0.0);
if (uPuffMode > 0.5) {
  float s=0.22+0.5*grow+0.15*uT; float d=length(p)-s*0.55;
  for(int i=0;i<7;i++){ float a=float(i)/7.0*6.2831+uSeed; vec2 c=vec2(cos(a),sin(a))*s*0.55;
    float rr=s*(0.36+0.14*fract(sin(float(i)*12.9898+uSeed)*43758.5)); d=min(d,length(p-c)-rr); }
  d += uT*uT*0.35;
  if (uPuffMode < 1.5) { if (d < 0.0) col=vec4(uPuff*mix(1.0,uGlow*0.6,0.5),1.0); }
  else { float ow=0.07; if (d<0.0 && d>-ow) col=vec4(uPuff*uGlow,1.0); else if (d<0.0) col=vec4(uPuff*0.35,0.25); }
}
float k=0.35+0.9*grow; vec2 q=p/k;
float star=max(0.0, 1.0-abs(q.x*q.y)*95.0-length(q)*1.05); float core=smoothstep(0.28,0.0,length(q));
float sa=clamp(star*2.2+core,0.0,1.0); vec3 sc=mix(uFlash*uGlow, vec3(uGlow*1.3), core);
col.rgb=mix(col.rgb,sc,sa); col.a=max(col.a,sa); col.a*=fade;
if (col.a < 0.01) discard; gl_FragColor=col;
}
